/**
 * Vite plugin for SQL lessons. Serves (in dev) and emits (in builds) the generated files of the SQL
 * runner, next to the hand-written public/sql-runner/index.html and host.js:
 *
 *   /sql-runner/worker.js      src/runner/sqlWorker.ts + sqlEngine.ts, bundled by Rolldown as one classic script
 *   /sql-runner/sql-wasm.js    sql.js (SQLite compiled to WebAssembly), straight from node_modules
 *   /sql-runner/sql-wasm.wasm
 *
 * Like csharp-runner/, the folder is deployed to the PREVIEW origin only (deploy/preview-host). It's
 * about 0.7 MB in all, so unlike C# there's no separate build step: sql.js is an npm dependency, so
 * upgrading SQLite is an `npm update`.
 */
import { readFileSync } from 'node:fs';
import { createRequire } from 'node:module';
import { join } from 'node:path';
import type { Plugin } from 'vite';

const BASE = '/sql-runner/';

async function bundleWorker(root: string): Promise<string> {
  const { build } = await import('rolldown');
  const result = await build({
    cwd: root,
    input: join(root, 'src/runner/sqlWorker.ts'),
    write: false,
    platform: 'browser',
    logLevel: 'silent',
    output: { format: 'iife', minify: true, codeSplitting: false },
  });
  const chunk = result.output.find((o) => o.type === 'chunk');
  if (!chunk || !('code' in chunk)) throw new Error('cg-sql-runner: no output for the worker');
  return `/* Codegrove SQL runner worker (generated by vite-plugins/sqlRunner.ts) */\n${chunk.code}`;
}

function sqlJsFile(root: string, name: string): Buffer {
  const require = createRequire(join(root, 'package.json'));
  return readFileSync(require.resolve(`sql.js/dist/${name}`));
}

export function sqlRunner(): Plugin {
  let root = process.cwd();
  return {
    name: 'cg-sql-runner',
    configResolved(config) {
      root = config.root;
    },
    configureServer(server) {
      server.middlewares.use(async (req, res, next) => {
        const path = req.url?.split('?')[0];
        if (!path?.startsWith(BASE)) return next();
        const file = path.slice(BASE.length);
        try {
          if (file === 'worker.js') {
            res.setHeader('Content-Type', 'text/javascript');
            res.setHeader('Cache-Control', 'no-cache');
            res.end(await bundleWorker(root)); // rebuilt on every load, so edits to the engine show up on reload
          } else if (file === 'sql-wasm.js' || file === 'sql-wasm.wasm') {
            res.setHeader('Content-Type', file.endsWith('.wasm') ? 'application/wasm' : 'text/javascript');
            res.end(sqlJsFile(root, file));
          } else {
            next(); // index.html and host.js come from public/
          }
        } catch (error) {
          next(error);
        }
      });
    },
    async generateBundle() {
      this.emitFile({ type: 'asset', fileName: 'sql-runner/worker.js', source: await bundleWorker(root) });
      for (const name of ['sql-wasm.js', 'sql-wasm.wasm']) {
        this.emitFile({ type: 'asset', fileName: `sql-runner/${name}`, source: sqlJsFile(root, name) });
      }
    },
  };
}
